import{_ as n,o as s,c as t,a4 as e}from"./chunks/framework.BRzJ4ijD.js";const h=JSON.parse('{"title":"QUIC","description":"","frontmatter":{},"headers":[],"relativePath":"networking/quic/index.md","filePath":"networking/quic/README.md","lastUpdated":1788475713000}'),l={name:"networking/quic/index.md"};function i(r,a,p,d,o,c){return s(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="quic" tabindex="-1">QUIC <a class="header-anchor" href="#quic" aria-label="Permalink to &quot;QUIC&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>QUIC 是 RFC 9000-9002 (2021) 定义的&quot;基于 UDP 的全新可靠传输 + 拥塞控制 + 集成 TLS 1.3&quot;。Google 从 2013 起内部实验，2018 ANRW 上 Cloudflare/Akamai/Fastly 加入，2022 RFC 9114 (HTTP/3) 标准化。本节我们走完 QUIC 的字节布局、CID-based 连接管理、stream 独立、connection migration、PTO/RACK 重传，以及产线上 4 大部署难点（UDP 中间盒、家用 NAT PMTU、负载均衡 CID 路由、0-RTT replay business ack）。</p><h2 id="章节" tabindex="-1">章节 <a class="header-anchor" href="#章节" aria-label="Permalink to &quot;章节&quot;">​</a></h2><ul><li><a href="./overview">QUIC over UDP：解决什么</a> — 协议演进动机、packet 字节布局、frame 类型、与 TCP/TLS 栈对比</li><li><a href="./0rtt">0-RTT / 连接迁移</a> — early data workflow、PSK resumption、connection migration、PATH_CHALLENGE 流程</li><li><a href="./bbr">BBR 在 QUIC 下的表现</a> — ack_delay 字段、stream 独立 cwnd、QUIC over UDP 拥塞控制部署观测</li></ul><hr><h2 id="quic-时间线" tabindex="-1">QUIC 时间线 <a class="header-anchor" href="#quic-时间线" aria-label="Permalink to &quot;QUIC 时间线&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2012   Google 内部实验性 QUIC (GAQ)</span></span>
<span class="line"><span>2016   NTT 测试 QUIC，IEFT BOF 起草</span></span>
<span class="line"><span>2018   IETF WG 正式 draft-ietf-quic-transport-00</span></span>
<span class="line"><span>2021   RFC 9000 (transport) + 9001 (TLS) + 9002 (recovery) published</span></span>
<span class="line"><span>2022   RFC 9114 (HTTP/3) published</span></span>
<span class="line"><span>2023   RFC 9369 (version negotiation) + 9390 (DPLPMTUD)</span></span>
<span class="line"><span>        BBR v3 + quiche 全网部署</span></span></code></pre></div><h2 id="quic-vs-tcp-tls-协议栈" tabindex="-1">QUIC vs TCP+TLS 协议栈 <a class="header-anchor" href="#quic-vs-tcp-tls-协议栈" aria-label="Permalink to &quot;QUIC vs TCP+TLS 协议栈&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP/1.1 over TCP+TLS 1.2:</span></span>
<span class="line"><span>   HTTP   →   TLS 1.2   →   TCP   →   IP   →   Ethernet</span></span>
<span class="line"><span>              ↑             ↑</span></span>
<span class="line"><span>              2 握手 RTT     3-way + cwnd build</span></span>
<span class="line"><span></span></span>
<span class="line"><span>HTTP/2 over TCP+TLS 1.3:</span></span>
<span class="line"><span>   HTTP/2 →   TLS 1.3   →   TCP   →   IP   →   Ethernet</span></span>
<span class="line"><span>              ↑             ↑</span></span>
<span class="line"><span>              1+0 RTT       3-way + cwnd</span></span>
<span class="line"><span></span></span>
<span class="line"><span>HTTP/3 over QUIC:</span></span>
<span class="line"><span>   HTTP/3 →   QUIC (含 TLS 1.3)   →   UDP   →   IP   →   Ethernet</span></span>
<span class="line"><span>              ↑                    ↑</span></span>
<span class="line"><span>              1+0 RTT 单达成合       no SYN, no connect</span></span></code></pre></div><p>QUIC 把 TLS 1.3 握手 encode 在 CRYPTO frame 里，与 packet 同步发出 + 接收 → 1 RTT 完成。</p><h2 id="quic-解决-tcp-自带-5-大痛点" tabindex="-1">QUIC 解决 TCP 自带 5 大痛点 <a class="header-anchor" href="#quic-解决-tcp-自带-5-大痛点" aria-label="Permalink to &quot;QUIC 解决 TCP 自带 5 大痛点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>TCP 痛点</th><th>在 TCP 中的根因</th><th>QUIC 解决方案</th></tr></thead><tbody><tr><td>HoL blocking (TCP stream HoL)</td><td>TCP 序号 byte-stream，client 无法选择性 ACK 单 stream 内字节</td><td>每 stream 独立 ack + 独立重传</td></tr><tr><td>握手 RTT 高</td><td>TCP 3-way + TLS 握手不重叠</td><td>CRYPTO frame + TLS 1.3 内嵌，1 RTT</td></tr><tr><td>连接 4 元组绑定</td><td>TCP 5-tuple NAT 表项随源 IP/port 变化</td><td>Connection ID 恒定，路由不靠 5-tuple</td></tr><tr><td>中间盒缓存语义</td><td>NAT/firewall 缓存 seq，重传包注入歧义</td><td>协议在 user space + packet number 单调</td></tr><tr><td>升级慢</td><td>内核 TCP，10 年才能全 clan</td><td>QUIC 在 user space，库升级</td></tr><tr><td>RTT 估不准</td><td>ACK delay 看不到</td><td>ACK frame 含 ack_delay 显式字段</td></tr><tr><td>应用层 HoL (HTTP/1.1 串行)</td><td>HTTP/1.1 自身限制</td><td>直接走 HTTP/3</td></tr></tbody></table><hr><h2 id="这一章带走的东西" tabindex="-1">这一章带走的东西 <a class="header-anchor" href="#这一章带走的东西" aria-label="Permalink to &quot;这一章带走的东西&quot;">​</a></h2><ol><li>QUIC 把 transport + congestion control + TLS 1.3 完全集成在 user space，1 RTT 握手是核心收益</li><li>CID 是独立于 5-tuple 的 conn 标识，让连接迁移与 LB routing 解耦</li><li>0-RTT、DPLPMTUD、ECN、ack_delay 是 QUIC 必修字段</li><li>NAT rebinding + 跨 ISP 链路切换是 QUIC 在移动网络杀手锏</li><li>部署仍有难点：UDP 中间盒被丢、负载均衡需要 CID 一致、客户端包兼容性</li></ol><h2 id="下一节-→" tabindex="-1">下一节 → <a class="header-anchor" href="#下一节-→" aria-label="Permalink to &quot;下一节 →&quot;">​</a></h2><p><a href="./overview">QUIC over UDP：解决什么</a> — packet 字节布局、long/short header、frame 类型、stream 编号、与 RTT 估计算法。</p>`,18)])])}const C=n(l,[["render",i]]);export{h as __pageData,C as default};
